const E=new TextEncoder(),D=new TextDecoder();
const J=(d,s=200,h={})=>new Response(JSON.stringify(d),{status:s,headers:{'content-type':'application/json;charset=utf-8',...h}});
const B=(m,s=400)=>J({error:m},s);
const clean=(x,n=5000)=>String(x??'').trim().slice(0,n),mail=x=>String(x??'').trim().toLowerCase();
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const ub=s=>{s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return Uint8Array.from(atob(s),c=>c.charCodeAt(0))};
const rand=()=>b64(crypto.getRandomValues(new Uint8Array(24)));
const shortRand=()=>b64(crypto.getRandomValues(new Uint8Array(4)));

async function uniqueShortToken(env){for(let i=0;i<8;i++){const t=shortRand();if(!await env.DB.prepare('SELECT id FROM share_tokens WHERE token=?').bind(t).first())return t}return shortRand()}
async function hmac(sec,data){const k=await crypto.subtle.importKey('raw',E.encode(sec),{name:'HMAC',hash:'SHA-256'},false,['sign']);return b64(await crypto.subtle.sign('HMAC',k,E.encode(data)))}
async function makeTok(sec,p){const x=b64(E.encode(JSON.stringify(p)));return x+'.'+await hmac(sec,x)}
async function readTok(sec,t){if(!sec||!t)return null;const [x,s]=t.split('.');if(!x||!s)return null;try{if((await hmac(sec,x))!==s)return null;const p=JSON.parse(D.decode(ub(x)));return p.exp>Date.now()?p:null}catch{return null}}
async function phash(p,s){s=s?ub(s):crypto.getRandomValues(new Uint8Array(16));const k=await crypto.subtle.importKey('raw',E.encode(p),'PBKDF2',false,['deriveBits']);const z=await crypto.subtle.deriveBits({name:'PBKDF2',salt:s,iterations:100000,hash:'SHA-256'},k,256);return{hash:b64(z),salt:b64(s)}}
const cookie=(v,max=604800)=>`jn_session=${v}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${max}`;
async function body(r){try{return await r.json()}catch{return{}}}
async function userOf(env,req){const raw=req.headers.get('Cookie')?.match(/(?:^|;\s*)jn_session=([^;]+)/)?.[1];const t=await readTok(env.SESSION_SECRET,raw);if(!t)return null;return env.DB.prepare('SELECT id,name,email,role,status FROM users WHERE id=?').bind(t.uid).first()}
async function planOf(env,uid){try{const r=await env.DB.prepare('SELECT plan FROM user_plans WHERE user_id=?').bind(uid).first();return r?.plan==='ultimate'?'ultimate':'premium'}catch{return'premium'}}
const limits=p=>p==='ultimate'?{gen:6,down:6,members:20,sideDown:2}:{gen:3,down:2,members:5,sideDown:2};
const price=(p,e)=>p==='ultimate'?Number(e.ULTIMATE_PRICE||100000):Number(e.PREMIUM_PRICE||50000);
const pname=p=>[p?.first_name,p?.last_name].filter(Boolean).join(' ');
const age=(b,d='')=>{if(!b)return null;const a=new Date(b+'T00:00:00'),z=d?new Date(d+'T00:00:00'):new Date();if(Number.isNaN(a.getTime())||Number.isNaN(z.getTime()))return null;let n=z.getFullYear()-a.getFullYear();if(z.getMonth()<a.getMonth()||(z.getMonth()===a.getMonth()&&z.getDate()<a.getDate()))n--;return n<0?null:n};
async function tree(env,id){return env.DB.prepare('SELECT * FROM family_trees WHERE id=?').bind(id).first()}
async function refreshAutoTreeName(env,tid){const t=await tree(env,tid);if(!t||!Number(t.auto_name))return;const r=await env.DB.prepare("SELECT p.* FROM persons p WHERE p.tree_id=? AND COALESCE(p.main_visible,1)=1 AND p.gender='male' AND NOT EXISTS(SELECT 1 FROM relationships r WHERE r.tree_id=p.tree_id AND r.to_person_id=p.id AND r.type='parent') ORDER BY CASE WHEN p.birth_date='' THEN 1 ELSE 0 END,p.birth_date,p.id LIMIT 1").bind(tid).first();const n=r?pname(r):'Silsilah Keluarga';await env.DB.prepare('UPDATE family_trees SET name=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(n,tid).run()}
async function ensureTreeRoot(env,tid){const t=await tree(env,tid);if(!t)return null;let cur=Number(t.root_person_id||0);if(cur){const cp=await env.DB.prepare("SELECT id,gender FROM persons WHERE id=? AND tree_id=?").bind(cur,tid).first();if(cp&&cp.gender==='male'){const maleParent=await env.DB.prepare("SELECT p.id FROM relationships r JOIN persons p ON p.id=r.from_person_id WHERE r.tree_id=? AND r.to_person_id=? AND r.type='parent' AND p.gender='male' ORDER BY r.id LIMIT 1").bind(tid,cur).first();if(!maleParent)return cur;cur=Number(maleParent.id)}}let r=await env.DB.prepare("SELECT p.id FROM persons p WHERE p.tree_id=? AND COALESCE(p.main_visible,1)=1 AND p.gender='male' AND NOT EXISTS(SELECT 1 FROM relationships x JOIN persons pp ON pp.id=x.from_person_id WHERE x.tree_id=p.tree_id AND x.to_person_id=p.id AND x.type='parent' AND pp.gender='male') ORDER BY CASE WHEN p.sibling_order=0 THEN 1 ELSE 0 END,p.sibling_order,CASE WHEN p.birth_date='' THEN 1 ELSE 0 END,p.birth_date,p.id LIMIT 1").bind(tid).first();if(!r)r=await env.DB.prepare("SELECT p.id FROM persons p WHERE p.tree_id=? AND COALESCE(p.main_visible,1)=1 AND NOT EXISTS(SELECT 1 FROM relationships x WHERE x.tree_id=p.tree_id AND x.to_person_id=p.id AND x.type='parent') ORDER BY p.id LIMIT 1").bind(tid).first();const id=Number(r?.id||cur||0)||null;await env.DB.prepare('UPDATE family_trees SET root_person_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(id,tid).run();return id}
async function validateSpouse(env,tid,a,z){const pa=await env.DB.prepare('SELECT id,gender,death_date FROM persons WHERE id=? AND tree_id=?').bind(a,tid).first(),pz=await env.DB.prepare('SELECT id,gender,death_date FROM persons WHERE id=? AND tree_id=?').bind(z,tid).first();if(!pa||!pz)return {error:'Anggota relasi tidak ditemukan.'};if(pa.gender==='other'||pz.gender==='other'||pa.gender===pz.gender)return {error:'Relasi pasangan harus antara laki-laki (suami) dan perempuan (istri).'};const husband=pa.gender==='male'?pa:pz,wife=pa.gender==='female'?pa:pz;const active=await env.DB.prepare("SELECT r.id,p.id partner_id,p.gender,p.death_date FROM relationships r JOIN persons p ON p.id=CASE WHEN r.from_person_id=? THEN r.to_person_id ELSE r.from_person_id END WHERE r.tree_id=? AND (r.from_person_id=? OR r.to_person_id=?) AND r.type='spouse' AND COALESCE(r.spouse_status,'active')='active' AND COALESCE(r.end_date,'')='' LIMIT 1").bind(wife.id,tid,wife.id,wife.id).first();if(active){if(active.death_date){await env.DB.prepare("UPDATE relationships SET spouse_status='ended',end_date=COALESCE(end_date,?) WHERE id=?").bind(active.death_date,active.id).run()}else{return {error:'Istri tersebut masih memiliki suami yang aktif. Selesaikan hubungan pasangan sebelumnya terlebih dahulu.'}}}return {husband,wife}}
async function graph(env,tid){const ps=(await env.DB.prepare('SELECT * FROM persons WHERE tree_id=?').bind(tid).all()).results||[],rs=(await env.DB.prepare('SELECT * FROM relationships WHERE tree_id=?').bind(tid).all()).results||[];const pa=new Map(),ch=new Map(),sp=new Map();const add=(m,k,v)=>{if(!m.has(k))m.set(k,[]);m.get(k).push(v)};for(const r of rs){if(r.type==='parent'){add(pa,r.to_person_id,r.from_person_id);add(ch,r.from_person_id,r.to_person_id)}else if(r.type==='spouse'){add(sp,r.from_person_id,r.to_person_id);add(sp,r.to_person_id,r.from_person_id)}}return{ps,rs,pa,ch,sp}}
function walk(start,map,n){const o=new Map([[start,0]]),q=[[start,0]];while(q.length){const[x,d]=q.shift();if(d>=n)continue;for(const y of map.get(x)||[])if(!o.has(y)){o.set(y,d+1);q.push([y,d+1])}}return o}
function siblings(start,g){const s=new Set();for(const p of g.pa.get(start)||[])for(const c of g.ch.get(p)||[])if(c!==start)s.add(c);return s}
function isSideAnchor(start,g,target){if(Number(start)===Number(target))return false;const ss=siblings(start,g);const side=new Set();for(const x of ss){side.add(Number(x));for(const y of walk(x,g.ch,2).keys())side.add(Number(y));}for(const x of [...side])for(const y of g.sp.get(x)||[])side.add(Number(y));return side.has(Number(target))}

function generationMap(start,g,n){const dist=new Map([[start,0]]),q=[start];while(q.length){const x=q.shift(),d=dist.get(x);if(Math.abs(d)>n)continue;for(const y of g.pa.get(x)||[])if(!dist.has(y)){dist.set(y,d-1);q.push(y)}for(const y of g.ch.get(x)||[])if(!dist.has(y)){dist.set(y,d+1);q.push(y)}for(const y of g.sp.get(x)||[])if(!dist.has(y)){dist.set(y,d);q.push(y)}for(const par of g.pa.get(x)||[])for(const sib of g.ch.get(par)||[])if(!dist.has(sib)){dist.set(sib,d);q.push(sib)}}return dist}
function memberScope(start,g,up,down){const ids=new Set([Number(start)]);const add=id=>{if(id!=null)ids.add(Number(id))};for(const x of walk(start,g.pa,up).keys())add(x);for(const x of walk(start,g.ch,down).keys())add(x);const ss=siblings(start,g);for(const x of ss){add(x);for(const y of walk(x,g.ch,2).keys()){add(y);for(const sp of g.sp.get(y)||[])add(sp)}}const initial=[...ids];for(const x of initial){for(const sp of g.sp.get(x)||[])add(sp)}for(const x of [...ids]){for(const sp of g.sp.get(x)||[]){for(const y of walk(sp,g.ch,down).keys())add(y)}}return ids}
function memberViewRoot(t,g,ids){const allowed=Array.from(ids).map(Number),set=new Set(allowed);const explicit=Number(t.root_person_id||0);if(explicit&&set.has(explicit)){const ep=g.ps.find(p=>Number(p.id)===explicit);if(ep&&ep.gender==='male')return explicit}const maleRoots=g.ps.filter(p=>set.has(Number(p.id))&&p.gender==='male'&&!(g.pa.get(p.id)||[]).some(x=>set.has(Number(x))&&g.ps.find(q=>Number(q.id)===Number(x))?.gender==='male')).sort((a,b)=>{const da=walk(a.id,g.pa,99).size,db=walk(b.id,g.pa,99).size;return db-da||Number(a.sibling_order||0)-Number(b.sibling_order||0)||String(pname(a)).localeCompare(String(pname(b)))||a.id-b.id});return Number(maleRoots[0]?.id||0)||Number(allowed[0]||0)||null}
async function membership(env,tid,uid){return env.DB.prepare("SELECT tm.*,p.first_name,p.last_name FROM tree_members tm JOIN persons p ON p.id=tm.person_id WHERE tm.tree_id=? AND tm.user_id=? AND tm.status='active'").bind(tid,uid).first()}
async function audit(env,tid,uid,a,t,id,details=''){try{await env.DB.prepare('INSERT INTO audit_logs(tree_id,actor_user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?,?)').bind(tid,uid,a,t,id||null,details).run()}catch{}}
async function ownerAccess(u,t){return u?.role==='member'&&t.created_by===u.id}
async function scoped(env,u,t){if(u.role!=='member'||t.created_by===u.id)return null;const m=await membership(env,t.id,u.id);if(!m)return null;const g=await graph(env,t.id),p=await planOf(env,t.created_by);return{m,g,ids:memberScope(m.person_id,g,limits(p).gen,limits(p).down),plan:p,planGen:limits(p).gen,planDown:limits(p).down,sideDown:limits(p).sideDown}}
let extrasReady=null;
async function columnExists(env,table,column){
 try{const r=await env.DB.prepare(`PRAGMA table_info(${table})`).all();return (r.results||[]).some(x=>x.name===column)}catch{return false}
}
async function addColumnIfMissing(env,table,column,ddl){
 if(!(await columnExists(env,table,column)))try{await env.DB.prepare(`ALTER TABLE ${table} ADD COLUMN ${ddl}`).run()}catch{}
}
async function ensureExtras(env){
 if(extrasReady)return extrasReady;
 extrasReady=(async()=>{
  const stmts=[
   "CREATE TABLE IF NOT EXISTS user_plans (user_id INTEGER PRIMARY KEY, plan TEXT NOT NULL CHECK(plan IN ('premium','ultimate')) DEFAULT 'premium', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS person_privacy (person_id INTEGER PRIMARY KEY, show_name INTEGER NOT NULL DEFAULT 1, show_age INTEGER NOT NULL DEFAULT 1, show_birth_date INTEGER NOT NULL DEFAULT 0, show_birth_place INTEGER NOT NULL DEFAULT 0, show_photo INTEGER NOT NULL DEFAULT 0, show_notes INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(person_id) REFERENCES persons(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS tree_members (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL, user_id INTEGER NOT NULL, person_id INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'member', status TEXT NOT NULL DEFAULT 'invited', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tree_id,user_id), UNIQUE(tree_id,person_id), FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(person_id) REFERENCES persons(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS invitations (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL, person_id INTEGER NOT NULL, invited_email TEXT NOT NULL DEFAULT '', invited_phone TEXT DEFAULT '', invited_by INTEGER NOT NULL, requester_id INTEGER, token TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, responded_at TEXT DEFAULT '', requested_at TEXT DEFAULT '', FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE, FOREIGN KEY(person_id) REFERENCES persons(id) ON DELETE CASCADE, FOREIGN KEY(invited_by) REFERENCES users(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS claim_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL, person_id INTEGER NOT NULL, requester_id INTEGER NOT NULL, note TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TEXT DEFAULT '', FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE, FOREIGN KEY(person_id) REFERENCES persons(id) ON DELETE CASCADE, FOREIGN KEY(requester_id) REFERENCES users(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS optional_lineages (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL, anchor_person_id INTEGER NOT NULL, linked_person_id INTEGER NOT NULL, relation_label TEXT NOT NULL DEFAULT 'Keluarga', sibling_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tree_id,anchor_person_id,linked_person_id), FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE, FOREIGN KEY(anchor_person_id) REFERENCES persons(id) ON DELETE CASCADE, FOREIGN KEY(linked_person_id) REFERENCES persons(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS share_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL UNIQUE, token TEXT NOT NULL UNIQUE, is_public INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL, actor_user_id INTEGER NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, details TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS family_branches (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL, anchor_person_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT DEFAULT '', generation_up INTEGER NOT NULL DEFAULT 2, generation_down INTEGER NOT NULL DEFAULT 2, created_by INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tree_id,anchor_person_id), FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE, FOREIGN KEY(anchor_person_id) REFERENCES persons(id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS branch_members (id INTEGER PRIMARY KEY AUTOINCREMENT, branch_id INTEGER NOT NULL, person_id INTEGER NOT NULL, source_type TEXT NOT NULL DEFAULT 'linked', context_role TEXT NOT NULL DEFAULT 'family', sibling_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(branch_id,person_id), FOREIGN KEY(branch_id) REFERENCES family_branches(id) ON DELETE CASCADE, FOREIGN KEY(person_id) REFERENCES persons(id) ON DELETE CASCADE)",
   "CREATE TABLE IF NOT EXISTS branch_relationships (id INTEGER PRIMARY KEY AUTOINCREMENT, branch_id INTEGER NOT NULL, from_person_id INTEGER NOT NULL, to_person_id INTEGER NOT NULL, type TEXT NOT NULL CHECK(type IN ('parent','spouse','sibling')), relation_label TEXT NOT NULL DEFAULT 'Keluarga', sibling_order INTEGER NOT NULL DEFAULT 0, spouse_status TEXT NOT NULL DEFAULT 'active', start_date TEXT DEFAULT '', end_date TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(branch_id,from_person_id,to_person_id,type), FOREIGN KEY(branch_id) REFERENCES family_branches(id) ON DELETE CASCADE, FOREIGN KEY(from_person_id) REFERENCES persons(id) ON DELETE CASCADE, FOREIGN KEY(to_person_id) REFERENCES persons(id) ON DELETE CASCADE)"
  ];
  // Run independently so one already-existing/legacy object cannot roll back the rest.
  for(const q of stmts){try{await env.DB.prepare(q).run()}catch{}}
  await addColumnIfMissing(env,'family_trees','auto_name','auto_name INTEGER NOT NULL DEFAULT 0');
  await addColumnIfMissing(env,'family_trees','root_person_id','root_person_id INTEGER');
  await addColumnIfMissing(env,'relationships','spouse_status',"spouse_status TEXT NOT NULL DEFAULT 'active'");
  await addColumnIfMissing(env,'relationships','start_date',"start_date TEXT DEFAULT ''");
  await addColumnIfMissing(env,'relationships','end_date',"end_date TEXT DEFAULT ''");
  await addColumnIfMissing(env,'person_privacy','show_notes','show_notes INTEGER NOT NULL DEFAULT 0');
  await addColumnIfMissing(env,'persons','sibling_order','sibling_order INTEGER NOT NULL DEFAULT 0');
  await addColumnIfMissing(env,'persons','title_prefix',"title_prefix TEXT NOT NULL DEFAULT ''");
  await addColumnIfMissing(env,'persons','title_suffix',"title_suffix TEXT NOT NULL DEFAULT ''");
  await addColumnIfMissing(env,'persons','main_visible','main_visible INTEGER NOT NULL DEFAULT 1');
  await addColumnIfMissing(env,'optional_lineages','sibling_order','sibling_order INTEGER NOT NULL DEFAULT 0');
  await addColumnIfMissing(env,'invitations','invited_phone',"invited_phone TEXT DEFAULT ''");
  await addColumnIfMissing(env,'invitations','requester_id','requester_id INTEGER');
  await addColumnIfMissing(env,'invitations','requested_at',"requested_at TEXT DEFAULT ''");
  for(const q of [
   "CREATE INDEX IF NOT EXISTS idx_persons_tree_order ON persons(tree_id,sibling_order,id)",
   "CREATE INDEX IF NOT EXISTS idx_persons_tree_main ON persons(tree_id,main_visible,sibling_order,id)",
   "CREATE INDEX IF NOT EXISTS idx_family_branches_tree ON family_branches(tree_id,active)",
   "CREATE INDEX IF NOT EXISTS idx_branch_members_branch ON branch_members(branch_id,sibling_order,person_id)",
   "CREATE INDEX IF NOT EXISTS idx_branch_relationships_branch ON branch_relationships(branch_id,type,sibling_order)"
  ]){try{await env.DB.prepare(q).run()}catch{}}
  try{await env.DB.prepare("INSERT OR IGNORE INTO user_plans(user_id,plan) SELECT id,'premium' FROM users WHERE role='member'").run()}catch{}
  try{await env.DB.prepare("INSERT OR IGNORE INTO person_privacy(person_id) SELECT id FROM persons").run()}catch{}
  // One-time compatibility conversion from V5 optional lineages. Keep it idempotent.
  try{
   const legacy=(await env.DB.prepare("SELECT DISTINCT o.tree_id,o.anchor_person_id,t.created_by,a.first_name,a.last_name FROM optional_lineages o JOIN family_trees t ON t.id=o.tree_id JOIN persons a ON a.id=o.anchor_person_id").all()).results||[];
   for(const x of legacy){
    try{await env.DB.prepare("INSERT OR IGNORE INTO family_branches(tree_id,anchor_person_id,name,description,generation_up,generation_down,created_by) VALUES(?,?,?,'Migrasi dari Silsilah Opsional V5.',2,2,?)").bind(x.tree_id,x.anchor_person_id,(`Cabang Keluarga ${String(x.first_name||'')} ${String(x.last_name||'')}`).trim(),x.created_by).run()}catch{}
    const fb=await env.DB.prepare("SELECT id FROM family_branches WHERE tree_id=? AND anchor_person_id=?").bind(x.tree_id,x.anchor_person_id).first();
    if(!fb)continue;
    try{await env.DB.prepare("INSERT OR IGNORE INTO branch_members(branch_id,person_id,source_type,context_role,sibling_order) VALUES(?,?, 'linked','anchor',0)").bind(fb.id,x.anchor_person_id).run()}catch{}
    const ors=(await env.DB.prepare("SELECT * FROM optional_lineages WHERE tree_id=? AND anchor_person_id=?").bind(x.tree_id,x.anchor_person_id).all()).results||[];
    for(const o of ors){
     try{
      const lab=String(o.relation_label||'Keluarga').toLowerCase();
      const type=['suami','istri'].includes(lab)?'spouse':lab==='saudara'?'sibling':'parent';
      const isParent=['ayah','ibu','kakek','nenek'].includes(lab);
      const from=isParent?o.linked_person_id:o.anchor_person_id,to=isParent?o.anchor_person_id:o.linked_person_id;
      await env.DB.prepare("INSERT OR IGNORE INTO branch_members(branch_id,person_id,source_type,context_role,sibling_order) VALUES(?,?, 'linked',?,?)").bind(fb.id,o.linked_person_id,lab,Number(o.sibling_order||0)).run();
      await env.DB.prepare("INSERT OR IGNORE INTO branch_relationships(branch_id,from_person_id,to_person_id,type,relation_label,sibling_order) VALUES(?,?,?,?,?,?)").bind(fb.id,from,to,type,o.relation_label||'Keluarga',Number(o.sibling_order||0)).run();
     }catch{}
    }
   }
  }catch{}
 })().catch(()=>{});
 return extrasReady;
}
function branchGraphRows(persons,rels){const byId=new Map(persons.map(p=>[Number(p.id),p])),parents=new Map(),children=new Map(),spouses=new Map(),siblingsMap=new Map();const add=(m,k,v)=>{if(!m.has(k))m.set(k,[]);m.get(k).push(v)};for(const r of rels){const a=Number(r.from_person_id),b=Number(r.to_person_id);if(r.type==='parent'){add(parents,b,a);add(children,a,b)}else if(r.type==='spouse'){add(spouses,a,b);add(spouses,b,a)}else if(r.type==='sibling'){add(siblingsMap,a,b);add(siblingsMap,b,a)}}return{byId,parents,children,spouses,siblings:siblingsMap}}
